-- BlueGate Store unified schema
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());

-- Private admin settings. Base prices and markups never need public SELECT access.
create table if not exists public.store_settings(
 id smallint primary key default 1 check(id=1),brand_name text not null default 'BlueGate',brand_subtitle text not null default 'Digital Services',hero_title text not null default 'سرویس‌های دیجیتال، ساده و سریع',hero_text text not null default 'VPN، تلگرام استارز و تلگرام پرمیوم با قیمت شفاف و سفارش مستقیم از پشتیبانی.',telegram_support text not null default 'bluegatesupport',telegram_channel text not null default 'BllueGate',footer_text text not null default 'سرویس‌های دیجیتال با پشتیبانی واقعی.',announcement_enabled boolean not null default true,announcement_text text not null default 'سرویس موردنظرت رو انتخاب کن و سفارش رو مستقیم بفرست پشتیبانی.',
 stars_price_basis text not null default 'usdt' check(stars_price_basis in('usdt','toman')),star_base_usdt numeric(18,8) not null default .015,star_base_toman numeric(18,2) not null default 2880,stars_markup numeric(8,3) not null default 20 check(stars_markup>=0),premium_markup numeric(8,3) not null default 20 check(premium_markup>=0),slider_min integer not null default 50,slider_max integer not null default 10000,slider_step integer not null default 25,slider_presets jsonb not null default '[100,500,1000,2500,5000]'::jsonb,
 smart_rounding_enabled boolean not null default true,round_small integer not null default 5000,round_medium integer not null default 10000,round_large integer not null default 20000,fallback_usdt_toman numeric(18,2) not null default 192000,show_reviews boolean not null default false,show_tutorials boolean not null default false,show_comparison boolean not null default true,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));

-- Public projection of settings. Contains only storefront data and final Stars unit sell price.
create table if not exists public.public_settings(
 id smallint primary key default 1 check(id=1),brand_name text not null,brand_subtitle text not null,hero_title text not null,hero_text text not null,telegram_support text not null,telegram_channel text not null,footer_text text not null,announcement_enabled boolean not null,announcement_text text not null,
 stars_price_basis text not null,star_sell_per_unit_usdt numeric(18,8) not null,star_sell_per_unit_toman numeric(18,4) not null,slider_min integer not null,slider_max integer not null,slider_step integer not null,slider_presets jsonb not null,
 smart_rounding_enabled boolean not null,round_small integer not null,round_medium integer not null,round_large integer not null,fallback_usdt_toman numeric(18,2) not null,show_reviews boolean not null,show_tutorials boolean not null,show_comparison boolean not null,updated_at timestamptz not null default now());

create table if not exists public.vpn_plans(id bigint generated by default as identity primary key,slug text unique not null,title text not null,subtitle text not null default '',note text not null default '',theme text not null default 'blue',icon text not null default '🛡️',pills jsonb not null default '[]'::jsonb,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.vpn_packages(id bigint generated by default as identity primary key,plan_id bigint not null references public.vpn_plans(id) on delete cascade,label text not null,price_toman numeric(18,2) not null default 0,sort_order integer not null default 0,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

-- Premium cost data is private; premium_public is the storefront projection.
create table if not exists public.premium_plans(id bigint generated by default as identity primary key,months integer not null,label text not null,base_usdt numeric(18,4) not null,markup_override numeric(8,3) check(markup_override is null or markup_override>=0),featured boolean not null default false,badge text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.premium_public(id bigint primary key references public.premium_plans(id) on delete cascade,months integer not null,label text not null,sell_usdt numeric(18,6) not null,featured boolean not null,badge text,active boolean not null,updated_at timestamptz not null default now());

create table if not exists public.discount_codes(id bigint generated by default as identity primary key,code text unique not null,percent numeric(6,2) not null check(percent>=0 and percent<=100),scope text not null default 'all' check(scope in('all','vpn','stars','premium')),enabled boolean not null default true,min_order numeric(18,2) not null default 0,max_uses integer,uses integer not null default 0,expires_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.content_settings(id smallint primary key default 1 check(id=1),features jsonb not null default '[]'::jsonb,faq jsonb not null default '[]'::jsonb,reviews jsonb not null default '[]'::jsonb,tutorials jsonb not null default '[]'::jsonb,comparison jsonb not null default '[]'::jsonb,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.audit_log(id bigint generated by default as identity primary key,table_name text,action text,changed_at timestamptz not null default now(),changed_by uuid references auth.users(id),row_id text,old_row jsonb,new_row jsonb);

alter table public.admin_users enable row level security;alter table public.store_settings enable row level security;alter table public.public_settings enable row level security;alter table public.vpn_plans enable row level security;alter table public.vpn_packages enable row level security;alter table public.premium_plans enable row level security;alter table public.premium_public enable row level security;alter table public.discount_codes enable row level security;alter table public.content_settings enable row level security;alter table public.audit_log enable row level security;

drop policy if exists admin_self on public.admin_users;create policy admin_self on public.admin_users for select to authenticated using(user_id=(select auth.uid()));
create policy public_settings_read on public.public_settings for select to anon,authenticated using(true);create policy vpn_plans_public_read on public.vpn_plans for select to anon,authenticated using(true);create policy vpn_packages_public_read on public.vpn_packages for select to anon,authenticated using(true);create policy premium_public_read on public.premium_public for select to anon,authenticated using(true);create policy content_public_read on public.content_settings for select to anon,authenticated using(true);
create policy store_admin_all on public.store_settings for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy public_settings_admin_all on public.public_settings for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy vpn_plans_admin_all on public.vpn_plans for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy vpn_packages_admin_all on public.vpn_packages for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy premium_admin_all on public.premium_plans for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy premium_public_admin_all on public.premium_public for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy discounts_admin_all on public.discount_codes for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy content_admin_all on public.content_settings for all to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid()))) with check(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));
create policy audit_admin_read on public.audit_log for select to authenticated using(exists(select 1 from public.admin_users a where a.user_id=(select auth.uid())));

grant select on public.public_settings,public.vpn_plans,public.vpn_packages,public.premium_public,public.content_settings to anon;grant select on public.admin_users,public.store_settings,public.public_settings,public.vpn_plans,public.vpn_packages,public.premium_plans,public.premium_public,public.discount_codes,public.content_settings,public.audit_log to authenticated;grant insert,update,delete on public.store_settings,public.public_settings,public.vpn_plans,public.vpn_packages,public.premium_plans,public.premium_public,public.discount_codes,public.content_settings to authenticated;grant usage,select on all sequences in schema public to authenticated;

create or replace function public.sync_public_settings() returns trigger language plpgsql security definer set search_path=public as $$begin
 insert into public.public_settings(id,brand_name,brand_subtitle,hero_title,hero_text,telegram_support,telegram_channel,footer_text,announcement_enabled,announcement_text,stars_price_basis,star_sell_per_unit_usdt,star_sell_per_unit_toman,slider_min,slider_max,slider_step,slider_presets,smart_rounding_enabled,round_small,round_medium,round_large,fallback_usdt_toman,show_reviews,show_tutorials,show_comparison,updated_at)
 values(new.id,new.brand_name,new.brand_subtitle,new.hero_title,new.hero_text,new.telegram_support,new.telegram_channel,new.footer_text,new.announcement_enabled,new.announcement_text,new.stars_price_basis,new.star_base_usdt*(1+new.stars_markup/100),new.star_base_toman*(1+new.stars_markup/100),new.slider_min,new.slider_max,new.slider_step,new.slider_presets,new.smart_rounding_enabled,new.round_small,new.round_medium,new.round_large,new.fallback_usdt_toman,new.show_reviews,new.show_tutorials,new.show_comparison,now())
 on conflict(id) do update set brand_name=excluded.brand_name,brand_subtitle=excluded.brand_subtitle,hero_title=excluded.hero_title,hero_text=excluded.hero_text,telegram_support=excluded.telegram_support,telegram_channel=excluded.telegram_channel,footer_text=excluded.footer_text,announcement_enabled=excluded.announcement_enabled,announcement_text=excluded.announcement_text,stars_price_basis=excluded.stars_price_basis,star_sell_per_unit_usdt=excluded.star_sell_per_unit_usdt,star_sell_per_unit_toman=excluded.star_sell_per_unit_toman,slider_min=excluded.slider_min,slider_max=excluded.slider_max,slider_step=excluded.slider_step,slider_presets=excluded.slider_presets,smart_rounding_enabled=excluded.smart_rounding_enabled,round_small=excluded.round_small,round_medium=excluded.round_medium,round_large=excluded.round_large,fallback_usdt_toman=excluded.fallback_usdt_toman,show_reviews=excluded.show_reviews,show_tutorials=excluded.show_tutorials,show_comparison=excluded.show_comparison,updated_at=now();return new;end$$;
create or replace function public.sync_premium_public() returns trigger language plpgsql security definer set search_path=public as $$declare m numeric;begin select coalesce(new.markup_override,premium_markup) into m from public.store_settings where id=1;insert into public.premium_public(id,months,label,sell_usdt,featured,badge,active,updated_at) values(new.id,new.months,new.label,new.base_usdt*(1+m/100),new.featured,new.badge,new.active,now()) on conflict(id) do update set months=excluded.months,label=excluded.label,sell_usdt=excluded.sell_usdt,featured=excluded.featured,badge=excluded.badge,active=excluded.active,updated_at=now();return new;end$$;
create or replace function public.resync_all_premium() returns trigger language plpgsql security definer set search_path=public as $$begin update public.premium_plans set updated_at=updated_at where true;return new;end$$;
drop trigger if exists sync_public_settings_trg on public.store_settings;create trigger sync_public_settings_trg after insert or update on public.store_settings for each row execute function public.sync_public_settings();
drop trigger if exists sync_premium_public_trg on public.premium_plans;create trigger sync_premium_public_trg after insert or update on public.premium_plans for each row execute function public.sync_premium_public();
drop trigger if exists resync_premium_markup_trg on public.store_settings;create trigger resync_premium_markup_trg after update of premium_markup on public.store_settings for each row execute function public.resync_all_premium();

create or replace function public.validate_discount(p_code text,p_scope text,p_amount numeric) returns table(valid boolean,percent numeric,message text) language plpgsql security definer set search_path=public as $$declare d public.discount_codes%rowtype;begin select * into d from public.discount_codes where upper(code)=upper(trim(p_code)) limit 1;if not found then return query select false,0::numeric,'not_found';return;end if;if not d.enabled then return query select false,0::numeric,'disabled';return;end if;if d.expires_at is not null and d.expires_at<now() then return query select false,0::numeric,'expired';return;end if;if d.max_uses is not null and d.uses>=d.max_uses then return query select false,0::numeric,'used_up';return;end if;if d.scope<>'all' and d.scope<>p_scope then return query select false,0::numeric,'scope';return;end if;if coalesce(p_amount,0)<d.min_order then return query select false,0::numeric,'minimum';return;end if;return query select true,d.percent,'ok';end $$;grant execute on function public.validate_discount(text,text,numeric) to anon,authenticated;

create or replace function public.bg_audit() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.audit_log(table_name,action,changed_by,row_id,old_row,new_row) values(tg_table_name,tg_op,(select auth.uid()),coalesce((case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end)->>'id',''),case when tg_op='INSERT' then null else to_jsonb(old) end,case when tg_op='DELETE' then null else to_jsonb(new) end);return coalesce(new,old);end$$;
DO $$declare t text;begin foreach t in array array['store_settings','vpn_plans','vpn_packages','premium_plans','discount_codes','content_settings'] loop execute format('drop trigger if exists bg_audit_trg on public.%I',t);execute format('create trigger bg_audit_trg after insert or update or delete on public.%I for each row execute function public.bg_audit()',t);end loop;end$$;

insert into public.store_settings(id) values(1) on conflict(id) do update set updated_at=public.store_settings.updated_at;
insert into public.content_settings(id,features,faq,reviews,tutorials,comparison) values(1,'[{"icon":"🚀","title":"سرعت بالا","text":"اتصال پایدار و پرسرعت بدون دردسر"},{"icon":"🔐","title":"امنیت کامل","text":"تمرکز روی حریم خصوصی و اتصال امن"},{"icon":"🎧","title":"پشتیبانی","text":"پاسخگویی سریع در تلگرام"},{"icon":"✅","title":"کیفیت تضمینی","text":"سرویس‌های تست‌شده با ضمانت بازگشت وجه"}]','[{"q":"سرویس‌ها روی چه دستگاه‌هایی قابل استفاده هستند؟","a":"اندروید، iOS، ویندوز، مک و لینوکس."},{"q":"Pro برای ترید مناسب است؟","a":"بله، پلن Pro برای استفاده حرفه‌ای و آی‌پی ثابت طراحی شده است."},{"q":"ضمانت بازگشت وجه دارید؟","a":"طبق شرایط اعلام‌شده فروشگاه، در صورت مشکل می‌توانی با پشتیبانی هماهنگ کنی."}]','[{"name":"امیررضا","rating":5,"text":"سرعت سرویس Pro خیلی خوب و پایدار بود."},{"name":"سارا","rating":5,"text":"پشتیبانی تلگرام سریع جواب داد."}]','[{"os":"اندروید","app":"v2rayNG","steps":["لینک اشتراک را کپی کن","داخل برنامه Import کن","اتصال را فعال کن"]},{"os":"iOS","app":"Streisand / V2Box","steps":["برنامه را نصب کن","Subscription را اضافه کن","Connect را بزن"]}]','[{"feature":"نوع آی‌پی","standard":"چند لوکیشن","pro":"ثابت","emergency":"ثابت اختصاصی"},{"feature":"مناسب ترید","standard":"خیر","pro":"عالی","emergency":"مناسب کار ضروری"},{"feature":"پایداری در اختلال","standard":"معمولی","pro":"بالا","emergency":"حداکثری"}]') on conflict(id) do nothing;
insert into public.vpn_plans(slug,title,subtitle,note,theme,icon,pills,sort_order) values('standard','BlueGate Standard','مولتی لوکیشن • سرعت قابل قبول • مناسب استفاده روزمره','هر گیگ اضافه ۵,۰۰۰ تومان','green','🛡️','[{"title":"مولتی لوکیشن"},{"title":"استفاده روزمره"}]',1),('pro','BlueGate Pro','تک لوکیشن • آی‌پی ثابت • مخصوص ترید و فعالیت‌های حرفه‌ای','هر گیگ اضافه ۱۰,۰۰۰ تومان','purple','🚀','[{"title":"آی‌پی ثابت"},{"title":"سرعت بالا"},{"title":"پایداری عالی"}]',2),('emergency','BlueGate Emergency','تک لوکیشن • آی‌پی ثابت • مخصوص زمان قطعی اینترنت','ویژه شرایط بحرانی','blue','⚡','[{"title":"مقاومت بالا"},{"title":"آی‌پی ثابت"},{"title":"پایداری بالا"}]',3) on conflict(slug) do nothing;
