insert into public.premium_plans(months,label,base_usdt,featured,badge) select 3,'3 ماهه',11.99,false,null where not exists(select 1 from public.premium_plans where months=3);insert into public.premium_plans(months,label,base_usdt,featured,badge) select 6,'6 ماهه',15.99,true,'پیشنهادی' where not exists(select 1 from public.premium_plans where months=6);insert into public.premium_plans(months,label,base_usdt,featured,badge) select 12,'12 ماهه',28.99,false,'بهترین ارزش خرید' where not exists(select 1 from public.premium_plans where months=12);insert into public.discount_codes(code,percent,scope,enabled) values('WELCOME10',10,'all',true) on conflict(code) do nothing;
